# -*- coding: utf-8 -*-
"""Collect only known own children and unchanged source/generated bytes."""
import json
from pathlib import Path
from evidence import OUT,WORK,load,raw,sha,write
identity=load(OUT/'independent-run.json');root=Path(identity['run_root']).resolve();assert root.is_relative_to(WORK)
phases=('N1','N6','N7');results=[]
for phase in phases:
    r=load(OUT/('result-'+phase+'.json'));assert r['successful'] and r['tests_run']==r['rounds']==1 and not r['other_groups_or_old_target_replayed'];results.append(r)
    imports=load(OUT/('imports-'+phase+'.json'))
    for m in imports['modules']:
        p=Path(m['actual_file']).resolve();assert p.is_relative_to(WORK) and sha(p.read_bytes())==m['sha256']
seed=load(OUT/'isolated-source-index.json')['files'];assert len(seed)==76
for row in seed:assert sha((OUT/row['file']).read_bytes())==row['sha256']
started=sorted(root.rglob('started.json'));records=[]
for path in started:
    d=path.parent;pre=load(d/'preregistered.json');start=load(path);end=load(d/'completed.json')
    assert pre['argv'] and pre['cwd'] and 0<pre['timeout_seconds']<=45
    assert start['pid']==end['pid'] and not end['alive'] and not end.get('timed_out',end.get('timeout',True))
    child=d==root/'processes/n1-child';expected=87 if child else 0;assert end['exit_code']==expected
    source='tests/test_a03_r8_r3_post_hold.py' if child else 'src/annotation/runtime/recovery/native_observation.py'
    digest=sha(raw(source));assert pre['script_sha256']==digest and sha((d/'script-snapshot.py').read_bytes())==digest
    if 'input_sha256' in pre:assert sha((d/'request.json').read_bytes())==pre['input_sha256']
    streams={name:(d/(name+'.txt')).read_bytes() for name in ('stdout','stderr')}
    for name,b in streams.items():
        if name+'_sha256' in end:assert sha(b)==end[name+'_sha256']
    records.append({'record':d.relative_to(OUT).as_posix(),'pid':end['pid'],'exit_code':end['exit_code'],'argv':pre['argv'],'cwd':pre['cwd'],
      'timeout_seconds':pre['timeout_seconds'],'alive':False,'timed_out':False,'source':source,'source_sha256':digest,
      'preregistered_sha256':sha((d/'preregistered.json').read_bytes()),'completed_sha256':sha((d/'completed.json').read_bytes()),
      'stdout_sha256':sha(streams['stdout']),'stderr_sha256':sha(streams['stderr'])})
assert len(started)==len(list(root.rglob('preregistered.json')))==len(list(root.rglob('completed.json')))==4
child=load(root/'processes/n1-child/completed.json');marker=load(root/'cases/N1/effect-committed.barrier.json')
assert child['exit_code']==87 and child['barrier_released'] and marker['pid']==child['pid'] and marker['point']=='AFTER_TARGET_EFFECT_COMMIT'
assert {p.name for p in (root/'cases').iterdir()}=={'N1','N7-before-completion'}
assert not list((WORK/'docs/evidence/A03/execution/P2-R8-R3-post-hold').glob('validation/*'))
for p in root.rglob('*'):
    if p.is_file() and p.name.endswith(('-wal','-journal')):assert p.stat().st_size==0
write(OUT/'independent-nested-release.json',{'status':'OWN_BOUNDED_NESTED_CHILDREN_EXITED','count':4,'records':records,
 'basis':'known preregistration/start/wait-completion and raw streams only; no OS/profile scan'})
files=[{'file':p.relative_to(OUT).as_posix(),'bytes':p.stat().st_size,'sha256':sha(p.read_bytes())} for p in sorted(root.rglob('*')) if p.is_file()]
write(OUT/'independent-output-index.json',{'run_id':identity['run_id'],'files':files,'phases_once':list(phases),'other_groups_or_old_target_replayed':False})
write(OUT/'independent-run-summary.json',{'status':'R4_N1_PREREQUISITE_N6_AND_N7_INITIALIZATION_LIMITED_PASSED','run_id':identity['run_id'],
 'results':results,'seed_files_unchanged':76,'nested_processes':4,'N1_effects':1,'N6_actual_recomputes':1,'N6_named_dependency_controls':1,
 'N7_runtime_hook_calls':1,'N7_normal_open_calls':1,'original_R3_N7':'FAILED_PRESERVED_READONLY_ONLY',
 'local_N2_N5_compatibility_variants_run':False,'field_reset':'NOT_EXECUTED_NO_RERUN_VARIANT_OR_DELEGATION'})
print(json.dumps({'status':'R4_N1_PREREQUISITE_N6_AND_N7_INITIALIZATION_LIMITED_PASSED','nested':4,'generated_files':len(files),'seed_files':76}))
